if(args.Length<3)throw new ArgumentException("Usage: enum-rewrite|simplify-runtime|pack-text INPUT OUTPUT [--game-bin DIRECTORY]");string command=args[0],input=args[1],output=args[2];switch(command){case "enum-rewrite":if(args.Length!=5||args[3]!="--game-bin")throw new ArgumentException("enum-rewrite requires --game-bin DIRECTORY");EnumAudit.Run(input,output,args[4]);break;case "simplify-runtime":File.WriteAllText(output,RuntimeSimplifier.Simplify(File.ReadAllText(input),true));break;case "api-aliases":ApiAliases.Run(input,output);break;case "pack-text":File.WriteAllText(output,TextPacking.PackText(File.ReadAllText(input)));break;default:throw new ArgumentException("Unknown transform: "+command);}